    static String html = "<div id=s><b id=x>a</b><i id=y>b</i><b id=z>c</b><em>d</em><b id=w>e</b></div>";
    static Document doc = Jsoup.parse(html);
    static void check(String q, String... expect) {
        var got = doc.select(q).eachAttr("id");
        var ok = got.equals(java.util.Arrays.asList(expect));
        System.out.println((ok?"PASS":"FAIL")+" "+q+" -> "+got+(ok?"":" expected "+java.util.Arrays.asList(expect)));
    }
    static void fail(String q) {
        try {
            QueryParser.parse(q);
            System.out.println("FAIL (no exception): "+q);
        } catch (Selector.SelectorParseException e) {
            System.out.println("PASS exception: "+q+" -> "+e.getMessage());
        }
    }
    public static void main(String[] a) {
        check("#s>:nth-child(2 of b)", "z");
        check("#s>:nth-last-child(1 of b,i)", "w");
        check("#s>:nth-child(1 of b)", "x");
        check("#s>:nth-child(odd of b)", "x", "w");
        check("#s>:nth-child(2n of b)", "z");
        check("#s>:nth-last-child(2 of b)", "z");
        check("#s>:nth-last-child(odd of b,i)", "w", "y");
        check("#s>:nth-child(of b)"); // invalid An+B
        check("#s>:nth-child(2 of b, i)", "z", "y"); // 2nd matching from start among b,i: x=1,y=2
        check("#s > b:nth-child(3)", "z"); // existing form
        check("#s > b:nth-of-type(2)", "z");
        check("#pseudo :nth-child(odd)");
        System.out.println(QueryParser.parse("#s>:nth-child(2n+1 of b.foo, i)").toString());
        // errors
        fail(":nth-child(2 of )");
        fail(":nth-child(2 of ");
        fail(":nth-child(2 of b");
        fail(":nth-child(2 of b,");
        fail(":nth-child(2 of)");
        fail(":nth-of-type(2 of b)");
        fail(":nth-last-of-type(2 of b)");
        fail(":nth-child()");
        fail(":nth-child(");
        fail(":nth-child(2 of b > )");
        // DOM unchanged?
        System.out.println(doc.body().html().equals(Jsoup.parse(html).body().html()) ? "DOM same" : "DOM CHANGED");
    }
}
