import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.QueryParser;
import org.jsoup.select.Selector;

public class Run2 {
    static void check(String html, String q, String... expect) {
        Document doc = Jsoup.parse(html);
        var got = doc.select(q).eachAttr("id");
        var ok = got.equals(java.util.Arrays.asList(expect));
        System.out.println((ok?"PASS":"FAIL")+" "+q+" -> "+got+(ok?"":" expected "+java.util.Arrays.asList(expect)));
    }
    static void fail(String q) {
        try { QueryParser.parse(q); System.out.println("FAIL (no exception): "+q); }
        catch (Selector.SelectorParseException e) { System.out.println("PASS exception: "+q); }
    }
    public static void main(String[] a) {
        // of S containing nested parens
        check("<div><b id=x><i></i></b><b id=y></b><b id=z><i></i></b></div>",
            "div>:nth-child(2 of b:has(i))", "z");
        // trailing combinator after the pseudo
        check("<div id=s><b id=x></b><b id=z><u id=u></u></b></div>",
            "#s>:nth-child(2 of b) u", "u");
        // of after odd
        check("<div><i id=i></i><b id=x></b><b id=z></b></div>",
            "div>:nth-child(odd of b)", "x");
        // plain spaced arg old behavior
        check("<div><p id=1>1</p><p id=2>2</p></div>", "div :nth-child( 2 )", "2");
        // uppercase OF keyword (CSS keywords are ASCII case-insensitive)
        check("<div id=s><b id=x>a</b><i id=y>b</i><b id=z>c</b></div>",
            "#s>:nth-child(2 OF b)", "z");
        // malformed
        fail(":nth-child(2 of b:has(.x)");
        fail(":nth-child(2 of [attr)");
        fail(":nth-child(2 of b:)");
        // candidate must also match S even when S is a type differing from tag
        check("<div><b id=x></b><i id=y></i><b id=z></b></div>",
            "div>b:nth-child(2 of i)"); // b can't match i -> empty
    }
}
EOF
